/*
# Seed center-hifz department + all missing content data

1. Purpose
- center-hifz is the only department without a seed migration (halqa, charity,
  school already have one). This inserts it.
- Also seeds announcements, posts, testimonials, timeline_events, and
  site_settings — all of which are empty on a fresh DB.

2. All inserts use ON CONFLICT DO NOTHING so re-running is safe.
*/

-- ============ center-hifz department ============
INSERT INTO departments (id, slug, name, short_description, full_description, mission, vision, values, objectives, established_date, logo_key, cover_image_key, cover_image, accent_color, stats, programs, telegram_link, telegram_chat_id, registration_status, registration_fields, requirements)
VALUES (
  'dept-hifz',
  'center-hifz',
  '{"ar":"مركز لحفظ القرآن الكريم دار القرآن","en":"Dar Al-Quran Quran Memorization Center","am":"የቁርአን ማስታወሻ ማዕከል","om":"Wiirtuu Hafzu Quraanaa Daar Al-Quraan"}'::jsonb,
  '{"ar":"مركز سكني لتخريج الحافظات لكتاب الله كاملاً، على يد نخبة من المعلمات المؤهلات","en":"A residential center for graduating female Hafizat of the complete Quran, taught by qualified female Ustazas","am":"የቁርአን ሙሉ ማስታወሻ ለሚያደርጉ ሴት ተማሪዎች የሚዘጋጀ ማዕከል፣ በብቁ የሴት መምህራን የሚማርበት","om":"Wiirtuu qophiiftuu hafzuu Quraana guutuu dubartoota barsiisuu, kan ogeeyyii Ustazaa dhiiraa"}'::jsonb,
  '{"ar":"مركز سكني متخصص في حفظ القرآن الكريم كاملاً للنساء، تأسس عام 1446هـ. يقدم المركز برنامجاً مكثفاً مدته سنتان، تُدرّس فيه المعلمات المؤهلات فقط. يوفر المركز جميع احتياجات الطالبات من السكن والطعام والمواد التعليمية ومستلزمات النظافة والرعاية الطبية، في بيئة آمنة ومحفزة على حفظ كتاب الله.","en":"A residential center specializing in the complete memorization of the Quran for women, established in 1446H. The center offers an intensive two-year program taught exclusively by qualified female Ustazas. It provides all student needs including accommodation, food, learning materials, hygiene supplies, and medical care in a safe environment conducive to memorizing the Book of Allah.","am":"ለሴቶች የቁርአን ሙሉ ማስታወሻ ለማድረግ የተዘጋጀ የመኖሪያ ማዕከል፣ በ1446ሂ የተመሰረተ። ማዕከሉ የሁለት ዓመት ጠንካራ ፕሮግራም ያቀርባል። ሁሉንም የተማሪዎችን ፍላጎቶች ያቀርባል።","om":"Wiirtuu qophiiftuu hafzuu Quraana guutuu dubartootaaf, 1446H kan hundeeffame. Piroogiraamii waggaa lamaa kan dandeessaa, kan Ustazaa dubartoota qofatu barsiisan. Haajiisa barattootaa hunda kenna."}'::jsonb,
  '{"ar":"تخريج حافظات متقنات لكتاب الله تعالى، متمكنات في العلوم الشرعية، مؤهلات لتعليم القرآن في مجتمعاتهن","en":"To graduate female Hafizat with precise mastery of the Book of Allah, competent in Islamic sciences, and qualified to teach the Quran in their communities","am":"የቁርአንን በትክክል የሚያስታውሱ እና ለማስተማር የሚበቁ ሴት ምሩቃን ማምረት","om":"Hafzuu Quraana sirrii qabuu fi hawaasa keessatti barsiisuu kan danda''u dubartoota baasuu"}'::jsonb,
  '{"ar":"أن يكون المركز منارة لحفظ كتاب الله تعالى للنساء في المنطقة، يُخرّج حافظات يجمعن بين الإتقان والفهم","en":"To be a beacon for women''s Quran memorization in the region, graduating Hafizat who combine mastery with understanding","am":"በክልሉ ለሴቶች የቁርአን ማስታወሻ መብራት መሆን፣ የሚያቀርብ ምሩቃን ማምረት","om":"Naannoo kanaatti dubartootaaf wiirtuu hafzu Quraanaa ta''uu, kan hubannoo fi sirrii qaban baasuu"}'::jsonb,
  '[{"ar":"الإتقان في الحفظ","en":"Mastery in memorization","am":"በማስታወሻ ትክክለኝነት","om":"Hafzuu keessatti sirrii"},{"ar":"الإخلاص لله تعالى","en":"Sincerity to Allah","am":"ለአላህ ቅንነት","om":"Rabbitti qajeelummaa"},{"ar":"الرعاية المتكاملة","en":"Comprehensive care","am":"የተሟላ እንክብካቤ","om":"Tajaasila guutuu"},{"ar":"الأخوّة في الله","en":"Sisterhood in Allah","am":"በአላህ የእህትነት ግንኙነት","om":"Haadha manaa Rabbii"}]'::jsonb,
  '[{"ar":"حفظ القرآن الكريم كاملاً مع الإتقان","en":"Memorize the complete Quran with mastery","am":"ቁርአንን በሙሉ በትክክል ማስታወስ","om":"Quraana guutuu sirrii hafzuu"},{"ar":"دراسة العلوم الشرعية المرافقة","en":"Study accompanying Islamic sciences","am":"የተያያዙ የእስላም ሳይንሶችን መማር","om":"Saayinsii Islaamaa walitti qabame qorachuu"},{"ar":"تأهيل المعلمات لنشر العلم","en":"Qualify teachers to spread knowledge","am":"ምሁራንን ለማሰልጠን","om":"Barsiisota beekumsa faca''uuf qopheessuu"}]'::jsonb,
  '1446 هـ',
  'center-hifz',
  'center-hifz',
  'https://images.pexels.com/photos/32108431/pexels-photo-32108431.jpeg?auto=compress&cs=tinysrgb&w=1600',
  '{"base":"#1E3A8A","accent":"#F59E0B"}'::jsonb,
  '[{"label":{"ar":"المقبولات في الدفعة الأولى","en":"Accepted in first batch","am":"በመጀመሪያው ወረቀት የተቀበሉ","om":"Dhabbata tokkoffaa qabiyyee"},"value":20},{"label":{"ar":"الخريجات بحفظ كامل","en":"Graduated with full memorization","am":"በሙሉ ማስታወሻ የተመረቁ","om":"Hafzuu guutuu milkaa''anii"},"value":18},{"label":{"ar":"الهدف للدفعة القادمة","en":"Target for next intake","am":"ለቀጣዩ ዒላማ","om":"Dhabbata itti aanfuu"},"value":30}]'::jsonb,
