  'open',
  '[{"name":"fullName","label":{"ar":"الاسم الكامل","en":"Full Name","am":"ሙሉ ስም","om":"Maqaa guddaa"},"type":"text","required":true},{"name":"phone","label":{"ar":"رقم الهاتف","en":"Phone Number","am":"ስልክ ቁጥር","om":"Lakkoofsa bilbila"},"type":"tel","required":true},{"name":"age","label":{"ar":"العمر","en":"Age","am":"ዕድሜ","om":"Umuri"},"type":"number","required":true},{"name":"educationLevel","label":{"ar":"المستوى التعليمي","en":"Education Level","am":"የትምህርት ደረጃ","om":"Sadarkaa barumsaa"},"type":"select","required":true,"options":[{"ar":"ابتدائي","en":"Elementary","am":"አንደኛ ደረጃ","om":"Sadarkaa tokkoffaa"},{"ar":"إعدادي","en":"Middle School","am":"ሁለተኛ ደረጃ","om":"Sadarkaa lammaffaa"},{"ar":"ثانوي","en":"High School","am":"ሦስተኛ ደረጃ","om":"Sadarkaa sadaffaa"},{"ar":"جامعي","en":"University","am":"ዩኒቨርሲቲ","om":"Yunivarsiitii"}]},{"name":"hifzLevel","label":{"ar":"مستوى الحفظ الحالي","en":"Current Memorization Level","am":"የአሁን ማስታወሻ ደረጃ","om":"Sadarkaa hafzuu ammaa"},"type":"select","required":true,"options":[{"ar":"لا شيء","en":"None","am":"የለም","om":"Homaa"},{"ar":"جزء عمّ","en":"Juz Amma","am":"ጁዝ አማ","om":"Juz Amma"},{"ar":"أكثر من جزء","en":"More than one Juz","am":"ከአንድ ጁዝ በላይ","om":"Dibaayye juzii"},{"ar":"حفظ كامل","en":"Complete Hifz","am":"ሙሉ ማስታወሻ","om":"Hafzuu guutuu"}]},{"name":"address","label":{"ar":"العنوان","en":"Address","am":"አድራሻ","om":"Teessoo"},"type":"text","required":false},{"name":"notes","label":{"ar":"ملاحظات","en":"Notes","am":"ማስታወሻዎች","om":"Gabaaboo"},"type":"textarea","required":false}]'::jsonb,
  '{"ar":"الشروط: أن تكون الطالبة مسلمة، متحمسة لحفظ القرآن كاملاً، قادرة على الالتزام بالبرنامج السكني المكثف لمدة سنتين، ولديها دعم من ولي أمرها. النجاح في المقابلة الشخصية وتقييم مستوى الحفظ.","en":"Requirements: The student must be Muslim, motivated to memorize the entire Quran, able to commit to the intensive two-year residential program, and have guardian support. Passing the personal interview and memorization level assessment.","am":"ሁኔታዎች፡ ተማሪዋ ሙስሊም መሆን፣ ቁርአንን ሙሉ ለማስታወስ ተነሳሽነት እንዳላት፣ ለሁለት ዓመት የመኖሪያ ፕሮግራም ለመከታተል መቻሉ፣ ከወላጆቿ ድጋፍ እንዳላት። የግል ቃለ-መጠይቅ ማለፍ።","om":"Eegumsa: Barartuun Muslimaatti, Quraana guutuu hafzuuf carraaqqi, waggaa lamaa piroogiraamii qophiif ta''e hordofuu danda''u, deggersa abbaa itti aanfamtootaa qabuu. Gaaffii dhuunfaa darbuu."}'::jsonb
)
